mapper.select:
SELECT
p.*,
s.name AS stationName

FROM parking_space_info p
LEFT JOIN station_info s ON p.station_id = s.id AND s.deleted = 0
WHERE p.deleted = 0


    AND p.id = #{pageReqVO.id}


    AND p.space_no LIKE CONCAT('%', #{pageReqVO.spaceNo}, '%')


    AND p.station_id = #{pageReqVO.stationId}


    AND p.garage LIKE CONCAT('%', #{pageReqVO.garage}, '%')


    AND p.location = #{pageReqVO.location}


    AND p.type = #{pageReqVO.type}


    AND p.device_type = #{pageReqVO.deviceType}


    AND p.qrcode = #{pageReqVO.qrcode}


    AND p.status = #{pageReqVO.status}


    AND p.real_status = #{pageReqVO.realStatus}


    AND p.bind_time BETWEEN #{pageReqVO.bindTime[0]} AND #{pageReqVO.bindTime[1]}


    AND p.bind_user_id = #{pageReqVO.bindUserId}


    AND p.device_id = #{pageReqVO.deviceId}


    AND p.status_update_time BETWEEN #{pageReqVO.statusUpdateTime[0]} AND #{pageReqVO.statusUpdateTime[1]}


    AND p.remark = #{pageReqVO.remark}


    AND p.reserve1 = #{pageReqVO.reserve1}


    AND p.reserve2 = #{pageReqVO.reserve2}


    AND p.creator = #{pageReqVO.creator}


    AND p.updater = #{pageReqVO.updater}


    AND p.create_time BETWEEN #{pageReqVO.createTime[0]} AND #{pageReqVO.createTime[1]}


    AND p.update_time BETWEEN #{pageReqVO.updateTime[0]} AND #{pageReqVO.updateTime[1]}


ORDER BY p.id DESC
